import{z as n,x as p,o as i,c as E,q as r,j as c,D as t,d as a,s,S as d,b as e}from"./chunks/framework.C8m1ZpeB.js";const v=JSON.parse('{"title":"字符设备与 ioctl","description":"","frontmatter":{"title":"字符设备与 ioctl","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chardev-ioctl.md","filePath":"cs/chardev-ioctl.md","lastUpdated":1791413859000}'),u={name:"cs/chardev-ioctl.md"};function f(B,o,m,D,_,A){const l=p("Mermaid");return i(),E("div",null,[o[2]||(o[2]=r('<h1 id="字符设备与-ioctl" tabindex="-1">字符设备与 ioctl <a class="header-anchor" href="#字符设备与-ioctl" aria-label="Permalink to &quot;字符设备与 ioctl&quot;">​</a></h1><div class="epigraph"><p>字符设备用 file_operations 提供 read/write/poll；ioctl 用命令号逃出「字节流」无法表达的设备控制。</p><footer>—— 据 Linux ioctl 文档；LDD 对 cdev 的说明；[设备节点](/cs/device-nodes) 为先修</footer></div><p><a href="/cs/device-model-binding">设备模型</a> 的 probe 常注册 <strong>cdev</strong>。<a href="/cs/vfs">VFS</a> 把 fd 指到 fops。缺口是 ioctl 的 ABI：命令编码、拷贝、与 <a href="/cs/copy-from-user">copy_from_user</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>字节流不能「取硬件随机数熵统计」或「设波特率」。<span class="marginnote">直觉类比：read/write 只会「往管道里倒水、从管道里接水」，说不清「把水管阀门拧到 45 度」这种命令。ioctl 就是文件接口旁边开的一扇侧门，专门塞那些不适合表达成字节流的设备控制动作——名字本义即 I/O control。</span>ioctl：<code>_IOW</code> 类宏编码方向与 magic。缺口：版本兼容；无类型检查导致内核读写用户；unlocked_ioctl。本课不把每个子系统的命令列出。</p><p><span class="marginnote">现代偏好 netlink、ioctl 减少、或 ioctl 经 bpf。对象仍是逃逸舱口。tun 已见过 fd 传包。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>open /dev/foo</code> → <code>unlocked_ioctl</code> → <code>copy_from_user</code> 结构 → 改硬件。对照 <a href="/cs/socket-options">setsockopt</a>：套接字的逃逸；ioctl 是文件的。对照 sysfs：属性文件更易脚本，不适合大二进制。对照 <a href="/cs/fuse">FUSE</a>：用户可实现 ioctl。</p>',8)),(i(),c(d,null,{default:t(()=>[s(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20FD%5B%22cdev%20fd%22%5D%20--%3E%20IOCTL%5B%22ioctl%20cmd%22%5D%0A%20%20IOCTL%20--%3E%20COPY%5B%22copy_from_user%22%5D%0A%20%20COPY%20--%3E%20HW%5B%22%E9%A9%B1%E5%8A%A8%E4%B8%8E%E7%A1%AC%E4%BB%B6%22%5D%0A"})]),fallback:t(()=>[...o[0]||(o[0]=[a(" Loading... ",-1)])]),_:1})),o[3]||(o[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),o[4]||(o[4]=e("p",null,[a("ioctl 让 Unix 文件抽象容纳设备个性，也是漏洞高发区。加固：copy 边界、cap 检查。不要写成 Windows DeviceIoControl 对照全文。与 "),e("a",{href:"/cs/kernel-audit"},"audit"),a("：可监视特定 ioctl。")],-1)),o[5]||(o[5]=e("p",null,"新接口优先避免 ioctl，但存量巨大。",-1)),o[6]||(o[6]=e("p",null,"实现上：命令号用 magic+序号+方向+大小编码，拷贝大小跟用户结构走，版本不对就内核读越界。一个 32 位命令号内部的四段拼装：",-1)),(i(),c(d,null,{default:t(()=>[s(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20CMD%5B%2232%20%E4%BD%8D%E5%91%BD%E4%BB%A4%E5%8F%B7%22%5D%20--%3E%20DIR%5B%22%E6%96%B9%E5%90%91%3A%202%20%E4%BD%8D%20%E8%AF%BB%E6%88%96%E5%86%99%22%5D%0A%20%20CMD%20--%3E%20SIZE%5B%22%E5%A4%A7%E5%B0%8F%3A%2014%20%E4%BD%8D%20%E5%8F%82%E6%95%B0%E5%AD%97%E8%8A%82%E6%95%B0%22%5D%0A%20%20CMD%20--%3E%20MAGIC%5B%22magic%3A%208%20%E4%BD%8D%20%E8%AE%BE%E5%A4%87%E7%B1%BB%E5%9E%8B%E5%AD%97%E6%AF%8D%22%5D%0A%20%20CMD%20--%3E%20SEQ%5B%22%E5%BA%8F%E5%8F%B7%3A%208%20%E4%BD%8D%20%E5%91%BD%E4%BB%A4%E7%BC%96%E5%8F%B7%22%5D%0A"})]),fallback:t(()=>[...o[1]||(o[1]=[a(" Loading... ",-1)])]),_:1})),o[7]||(o[7]=r('<p>unlocked_ioctl 不再持大内核锁，驱动自己串行化。<span class="marginnote">常见误区：初学者容易以为内核拿到用户传来的指针就能直接解引用。实际上用户指针可能是野指针、甚至指向已被换出的页，必须经 copy_from_user/copy_to_user 带边界检查地搬；漏掉这一步是内核漏洞的经典来源，轻则 oops 重则提权。</span> 读法上只引用<a href="/cs/device-model-binding">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 内核安全与启动」课序里，对象是 <strong>字符设备与 ioctl</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 compat_ioctl 的全部 32/64。不保证图形 DRM 的命令缓冲。下一课用户态如何对 uevent 反应：udev。</p><p>版本字段会变，课序钉的是机制对象「字符设备与 ioctl」，不是某一主线内核的结构体名。 后课默认：设备控制可走 ioctl。热插事件与 udev 规则，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cdev 用 fops；ioctl 传结构化命令。<span class="marginnote">数字实例：命令号里那段 14 位的「大小」字段最多表示 16383 字节；<code>_IOW(&#39;q&#39;, 1, struct foo)</code> 会在编译期把 <code>sizeof(struct foo)</code> 烧进命令号。若拷贝大小跟着新版头文件的 48 字节走，而用户缓冲还按旧版只留 32 字节，内核就从用户缓冲越界多读 16 字节——这就是「版本不对就读越界」的具体来源。</span></li><li>必须经 copy_*_user 并做特权检查。</li><li>udev 热插是下一课。</li><li>出处：LDD；ioctl(2)；Linux API。</li></ul>',8))])}const b=n(u,[["render",f]]);export{v as __pageData,b as default};
